// Generated by OrchestKit Claude Plugin
// Created: 2026-09-19
//
// Typeahead suggestions for the ⌘K search box, from the generated docs index
// (lib/generated/search-suggest-index: page titles + ATX headings, rebuilt by
// scripts/gen-search-suggest-index.mjs). Deterministic: prefix tiers first,
// then fuzzy (edit distance 1 on word prefixes, queries >= 4 chars), then a
// stable title/url tiebreak. No network, no randomness, no state.
//
// Optional Jev re-rank of the top 10 lives in app/api/search/suggest (server
// side, behind ORK_SITE_JEV_RERANK + TYPESAFE_API_KEY via lib/jev-rerank);
// the client only calls it when the flag was on at build time, so flag-off
// operation stays fully local.

import { osaDistance } from "@/lib/search-suggest";

export type SuggestEntry = {
	url: string;
	title: string;
	headings: readonly string[];
};

export type Suggestion = {
	/** Page URL, with `#anchor` appended when the match came via a heading. */
	url: string;
	title: string;
	/** What the user sees: page title, or `Title > heading`. */
	label: string;
	via: "title" | "heading";
};

function words(s: string): string[] {
	return s
		.toLowerCase()
		.split(/[^a-z0-9]+/)
		.filter(Boolean);
}

/** github-slugger-style heading anchor (matches rehype-slug output). */
export function anchorFor(heading: string): string {
	return heading
		.toLowerCase()
		.replace(/[^\p{L}\p{N}\s-]/gu, "")
		.trim()
		.replace(/\s+/g, "-");
}

/** Every query token must prefix-match a word of `text`. */
function allTokensPrefix(queryToks: readonly string[], text: string): boolean {
	const t = words(text);
	return (
		queryToks.length > 0 &&
		queryToks.every((qt) => t.some((w) => w.startsWith(qt)))
	);
}

/** Every query token hits a word by prefix or by 1-edit fuzzy (len >= 4). */
function allTokensFuzzy(queryToks: readonly string[], text: string): boolean {
	const t = words(text);
	return (
		queryToks.length > 0 &&
		queryToks.every(
			(qt) =>
				t.some((w) => w.startsWith(qt)) ||
				(qt.length >= 4 &&
					t.some(
						(w) =>
							osaDistance(qt, w, 2) <= 1 ||
							(w.length > qt.length &&
								osaDistance(qt, w.slice(0, qt.length + 1), 2) <= 1),
					)),
		)
	);
}

/**
 * Tiered score for one entry. Higher wins; 0 means no suggestion.
 *   title == query          120   exact
 *   title startsWith query   90   whole-string prefix
 *   title contains query     60   substring
 *   all tokens prefix title  40   per-word prefix coverage
 *   heading startsWith       30
 *   all tokens prefix a hdg  20
 *   fuzzy (distance 1)       12
 */
function scoreEntry(
	query: string,
	queryToks: readonly string[],
	entry: SuggestEntry,
	fuzzy: boolean,
): { score: number; via: "title" | "heading"; heading?: string } {
	const title = entry.title.toLowerCase();
	if (title === query) return { score: 120, via: "title" };
	if (title.startsWith(query)) return { score: 90, via: "title" };
	if (title.includes(query)) return { score: 60, via: "title" };
	if (allTokensPrefix(queryToks, entry.title)) {
		return { score: 40 + Math.min(queryToks.length, 5), via: "title" };
	}
	for (const heading of entry.headings) {
		const h = heading.toLowerCase();
		if (h.startsWith(query)) {
			return { score: 30, via: "heading", heading };
		}
	}
	for (const heading of entry.headings) {
		if (allTokensPrefix(queryToks, heading)) {
			return { score: 20, via: "heading", heading };
		}
	}
	if (fuzzy && allTokensFuzzy(queryToks, entry.title)) {
		return { score: 12, via: "title" };
	}
	return { score: 0, via: "title" };
}

/**
 * Top `max` suggestions for a query, one per page. Queries under 2 chars
 * return nothing (typeahead waits for a real signal). Deterministic order:
 * score desc, then label asc, then url asc.
 */
export function suggestCompletions(
	query: string,
	entries: readonly SuggestEntry[],
	max = 10,
): Suggestion[] {
	const q = query.trim().toLowerCase();
	if (q.length < 2) return [];
	const qToks = words(q);
	if (qToks.length === 0) return [];
	const fuzzy = q.length >= 4;

	const scored = entries
		.map((entry) => ({ entry, ...scoreEntry(q, qToks, entry, fuzzy) }))
		.filter((x) => x.score > 0)
		.sort(
			(a, b) =>
				b.score - a.score ||
				a.entry.title.localeCompare(b.entry.title) ||
				a.entry.url.localeCompare(b.entry.url),
		);

	return scored.slice(0, max).map(({ entry, via, heading }) => {
		const anchor = via === "heading" && heading ? `#${anchorFor(heading)}` : "";
		return {
			url: `${entry.url}${anchor}`,
			title: entry.title,
			label: heading ? `${entry.title} > ${heading}` : entry.title,
			via,
		};
	});
}

// ---------------------------------------------------------------------------
// Jev re-rank of the suggestion top-10 (server route only).
// ---------------------------------------------------------------------------

/**
 * One System One Choice request over the deterministic top-10; returns the
 * same suggestions in Jev order, or null on any failure. Runs only inside
 * app/api/search/suggest when ORK_SITE_JEV_RERANK + TYPESAFE_API_KEY are set.
 */
export async function jevSuggestOrder(
	query: string,
	suggestions: readonly Suggestion[],
	deps: {
		fetchImpl?: typeof fetch;
		apiKey?: string;
		timeoutMs?: number;
	} = {},
): Promise<Suggestion[] | null> {
	const { jevChoiceOrder } = await import("@/lib/jev-rerank");
	const order = await jevChoiceOrder(
		{
			instructions:
				"Which docs page is the most likely intended destination for this typed search prefix?",
			context: { query },
			candidates: suggestions.map((s) => ({ key: s.url, label: s.label })),
		},
		deps,
	);
	if (!order) return null;
	const byUrl = new Map(suggestions.map((s) => [s.url, s]));
	const out = order
		.map((u) => byUrl.get(u))
		.filter((s): s is Suggestion => Boolean(s));
	return out.length === suggestions.length ? out : null;
}
